<template>
  <view class="page">
    <view class="summary"><view><view class="eyebrow">学习愿望花园</view><view class="summary-title">{{ activeCount }} 个计划正在发芽</view></view><view class="summary-count">{{ plans.length }}</view></view>
    <view class="ai-hero" @click="goAI"><view class="ai-badge">AI</view><view class="ai-copy"><view class="ai-title">{{ aiTitle }}</view><view class="ai-desc">{{ aiDescription }}</view></view><view class="arrow">›</view></view>
    <view class="ai-status" v-if="aiJob"><view class="ai-state"><view class="ai-state-dot" :class="aiJob.status" /><view>{{ aiStatusText }}</view></view><view class="ai-result" v-if="aiJob.status === 'succeeded' && aiJob.result_plan_id" @click="openGeneratedPlan">查看计划 ›</view></view>
    <button class="manual" @click="openCreate">＋ 手动创建</button>
    <view class="tools"><view class="tool" @click="goSchedule">日程</view><view class="tool" @click="goGroup">小组</view><view class="tool" @click="goNotifications">提醒</view><view class="tool recovery" v-if="overdueCount" @click="goRecovery">重排 {{ overdueCount }}</view></view>
    <view class="section-head">我的计划</view>
    <view class="empty" v-if="!loading && !plans.length"><view class="empty-title">还没有计划</view><view class="empty-desc">从 AI 生成开始，或手动安排清晰的日期与时段。</view></view>
    <view class="cards" v-else>
      <view class="card" v-for="plan in plans" :key="plan.id" :class="{ paused: plan.status === 'paused' }" @click="openPlan(plan)">
        <view class="card-head"><view class="plan-title">{{ plan.title }}</view><view class="pill" :class="plan.status">{{ statusText(plan.status) }}</view></view>
        <view class="plan-desc" v-if="plan.description">{{ plan.description }}</view><view class="schedule">{{ weekdaySummary(plan.study_weekdays) }} · {{ plan.default_planned_start }}-{{ plan.default_planned_end }}</view>
        <view class="progress" v-if="plan.total_tasks"><view class="progress-copy"><text>完成 {{ plan.completed_tasks }}/{{ plan.total_tasks }}</text><text>{{ rate(plan) }}%</text></view><view class="track"><view class="fill" :style="{ width: `${rate(plan)}%` }" /></view></view><view class="taskless" v-else>尚未生成任务</view>
        <button class="invite" @click.stop="invite(plan)">邀请学习伙伴</button>
      </view>
    </view>
    <view class="sheet" v-if="showForm" @click.self="showForm=false"><view class="sheet-body">
      <view class="sheet-title">手动创建计划</view>
      <view class="field"><text>计划名称</text><input v-model="form.title" placeholder="例如：学习 Go 语言" @input="refreshDrafts" /></view>
      <view class="field"><text>计划说明</text><textarea v-model="form.description" placeholder="阶段目标或范围（可选）" /></view>
      <view class="grid"><view class="field"><text>开始日期</text><picker mode="date" :value="form.start_date" @change="setDate('start_date',$event)"><view class="picker">{{ form.start_date }}</view></picker></view><view class="field"><text>结束日期</text><picker mode="date" :value="form.end_date" :start="form.start_date" @change="setDate('end_date',$event)"><view class="picker">{{ form.end_date }}</view></picker></view></view>
      <view class="field"><text>学习日</text><view class="weekdays"><view v-for="day in weekdays" :key="day.value" :class="['weekday',{selected:form.study_weekdays?.includes(day.value)}]" @click="toggleWeekday(day.value)">{{ day.label }}</view></view></view>
      <view class="bulk"><view class="bulk-title">批量填写任务</view><input v-model="bulk.title" placeholder="共同标题" /><textarea v-model="bulk.objective" placeholder="共同目标" /><view class="grid"><picker mode="time" :value="bulk.planned_start" @change="setBulkTime('planned_start',$event)"><view class="picker">{{ bulk.planned_start }}</view></picker><picker mode="time" :value="bulk.planned_end" @change="setBulkTime('planned_end',$event)"><view class="picker">{{ bulk.planned_end }}</view></picker></view><button @click="applyBulk">应用到全部 {{ drafts.length }} 个任务</button></view>
      <view class="draft" v-for="(task,index) in drafts" :key="task.date"><view class="draft-date">{{ task.date }} · {{ weekdayLabel(task.date) }}</view><input v-model="task.title" placeholder="任务标题" /><textarea v-model="task.objective" placeholder="具体、可完成的任务目标" /><textarea v-model="task.description" placeholder="任务说明（可选）" /><view class="grid"><picker mode="time" :value="task.planned_start" @change="setTaskTime(index,'planned_start',$event)"><view class="picker">{{ task.planned_start }}</view></picker><picker mode="time" :value="task.planned_end" @change="setTaskTime(index,'planned_end',$event)"><view class="picker">{{ task.planned_end }}</view></picker></view></view>
      <view class="form-error" v-if="formError">{{ formError }}</view><label class="confirm"><checkbox :checked="!!form.confirm_overload" @click="form.confirm_overload=!form.confirm_overload" />允许继续处理非时间类负荷提醒</label>
      <view class="sheet-actions"><button class="secondary" @click="showForm=false">取消</button><button class="primary" @click="save">创建计划</button></view>
    </view></view>
  </view>
</template>

<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { onHide, onShow, onUnload } from '@dcloudio/uni-app'
import { AIApi, PlanApi, RecoveryApi, type AIPlanJob, type CreatePlanReq, type Plan, type TaskDraft } from '@/api'
import { addLocalDays, localDateKey } from '@/utils/date'
import { formatScheduleConflicts } from '@/utils/schedule'

const plans=ref<Plan[]>([]),loading=ref(false),overdueCount=ref(0),showForm=ref(false),formError=ref('')
const aiJob=ref<AIPlanJob|null>(null)
const weekdays=[{value:1,label:'一'},{value:2,label:'二'},{value:3,label:'三'},{value:4,label:'四'},{value:5,label:'五'},{value:6,label:'六'},{value:7,label:'日'}]
const form=reactive<CreatePlanReq>({title:'',description:'',weekly_target_hours:7,start_date:'',end_date:'',default_planned_start:'20:00',default_planned_end:'21:00',study_weekdays:[1,2,3,4,5],confirm_overload:false})
const bulk=reactive({title:'',objective:'',planned_start:'20:00',planned_end:'21:00'}),drafts=ref<TaskDraft[]>([])
const activeCount=computed(()=>plans.value.filter(plan=>plan.status==='active').length)
const hasActiveAIJob=computed(()=>aiJob.value?.status==='pending'||aiJob.value?.status==='running')
const aiTitle=computed(()=>hasActiveAIJob.value?'AI 正在生成计划':aiJob.value?.status==='succeeded'?'AI 计划已生成':aiJob.value?.status==='failed'?'AI 计划生成失败':'AI 生成计划')
const aiDescription=computed(()=>aiJob.value?.status==='pending'?'任务已排队，离开页面也会继续':aiJob.value?.status==='running'?'后台正在规划并校验学习日程':aiJob.value?.status==='succeeded'?'计划已自动保存，可查看或再次生成':aiJob.value?.status==='failed'?'调整目标或可用时间后可以重试':'说出目标，自动拆成有日期、有节奏的学习任务')
const aiStatusText=computed(()=>aiJob.value?.status==='pending'?'等待处理':aiJob.value?.status==='running'?'生成中':aiJob.value?.status==='succeeded'?'生成完成':`生成失败：${aiJob.value?.error_message||'请调整条件后重试'}`)
let pageVisible=false,aiPollTimer:ReturnType<typeof setTimeout>|undefined,aiPollSequence=0
async function load(){loading.value=true;try{const [rows,recovery,currentJob]=await Promise.all([PlanApi.list(),RecoveryApi.preview().catch(()=>null),AIApi.currentPlanJob().catch(()=>null)]);if(!pageVisible)return;plans.value=rows||[];overdueCount.value=recovery?.overdue_tasks||0;aiJob.value=currentJob;scheduleAIPoll()}catch(error:any){if(pageVisible)uni.showToast({title:error?.message||'加载失败',icon:'none'})}finally{loading.value=false}}
async function pollAIJob(){const current=aiJob.value;if(!pageVisible||!current||!hasActiveAIJob.value)return;const sequence=++aiPollSequence;try{const updated=await AIApi.getPlanJob(current.id);if(!pageVisible||sequence!==aiPollSequence)return;const completed=!hasActiveAIJob.value||updated.status==='succeeded'||updated.status==='failed';aiJob.value=updated;if(completed&&updated.status==='succeeded'){plans.value=await PlanApi.list()||[]}}catch{}if(pageVisible&&sequence===aiPollSequence&&hasActiveAIJob.value)scheduleAIPoll()}
function scheduleAIPoll(){stopAIPollTimer();if(pageVisible&&hasActiveAIJob.value)aiPollTimer=setTimeout(pollAIJob,2000)}
function stopAIPollTimer(){if(aiPollTimer)clearTimeout(aiPollTimer);aiPollTimer=undefined}
function stopAIPolling(){pageVisible=false;aiPollSequence++;stopAIPollTimer()}
function openCreate(){const start=new Date();Object.assign(form,{title:'',description:'',weekly_target_hours:7,start_date:localDateKey(start),end_date:localDateKey(addLocalDays(start,6)),default_planned_start:'20:00',default_planned_end:'21:00',study_weekdays:[1,2,3,4,5],confirm_overload:false});Object.assign(bulk,{title:'',objective:'',planned_start:'20:00',planned_end:'21:00'});formError.value='';drafts.value=[];refreshDrafts();showForm.value=true}
function selectedDates(){if(!form.start_date||!form.end_date||form.start_date>form.end_date)return[];const selected=new Set(form.study_weekdays||[]),dates:string[]=[];for(let day=new Date(`${form.start_date}T12:00:00`),end=new Date(`${form.end_date}T12:00:00`);day<=end;day=addLocalDays(day,1)){const weekday=day.getDay()||7;if(selected.has(weekday))dates.push(localDateKey(day))}return dates}
function refreshDrafts(){const previous=new Map(drafts.value.map(row=>[row.date,row]));drafts.value=selectedDates().map(date=>previous.get(date)||{date,title:form.title,objective:'',description:'',planned_start:'20:00',planned_end:'21:00'})}
function applyBulk(){for(const task of drafts.value){task.title=bulk.title||task.title;task.objective=bulk.objective||task.objective;task.planned_start=bulk.planned_start;task.planned_end=bulk.planned_end}}
function toggleWeekday(value:number){const selected=form.study_weekdays||[];form.study_weekdays=selected.includes(value)?selected.filter(item=>item!==value):[...selected,value].sort();refreshDrafts()}
function setDate(field:'start_date'|'end_date',event:any){form[field]=event.detail.value;refreshDrafts()}
function setBulkTime(field:'planned_start'|'planned_end',event:any){bulk[field]=event.detail.value}
function setTaskTime(index:number,field:'planned_start'|'planned_end',event:any){drafts.value[index][field]=event.detail.value}
async function save(){formError.value='';if(!form.title.trim()||!drafts.value.length)return void(formError.value='请填写计划名称并选择至少一个学习日期');for(const task of drafts.value){if(!task.title.trim()||!task.objective.trim())return void(formError.value=`请完整填写 ${task.date} 的标题和目标`);if(task.planned_start>=task.planned_end)return void(formError.value=`${task.date} 的结束时间须晚于开始时间`)}const request={...form,task_drafts:drafts.value};try{await PlanApi.validateSchedule(request);await PlanApi.create(request);showForm.value=false;await load();uni.showToast({title:'计划已创建',icon:'success'})}catch(error:any){formError.value=scheduleError(error)||error?.message||'创建失败'}}
function scheduleError(error:any){const rows=error?.raw?.invalid_tasks;return Array.isArray(rows)?formatScheduleConflicts(rows.map((row:any)=>({...row,id:row.task_id,conflicting_tasks:row.conflicting_tasks||[]}))):''}
function invite(plan:Plan){uni.navigateTo({url:`/pages/plan-detail/plan-detail?id=${plan.id}&invite=1`})}function openPlan(plan:Plan){uni.navigateTo({url:`/pages/plan-detail/plan-detail?id=${plan.id}`})}
function weekdayLabel(date:string){return `周${weekdays.find(row=>row.value===(new Date(`${date}T12:00:00`).getDay()||7))?.label}`}
function weekdaySummary(selected:unknown){const days=Array.isArray(selected)?selected:[];return days.length===7?'每天':days.length?`周${days.map(value=>weekdays.find(day=>day.value===value)?.label).join('、')}`:'未设置学习日'}
function rate(plan:Plan){return plan.completion_rate??(plan.total_tasks?Math.round(plan.completed_tasks/plan.total_tasks*100):0)}function statusText(status:string){return status==='paused'?'暂停':status==='archived'?'归档':'进行中'}
function openGeneratedPlan(){if(aiJob.value?.result_plan_id)uni.navigateTo({url:`/pages/plan-detail/plan-detail?id=${aiJob.value.result_plan_id}`})}
function goAI(){uni.navigateTo({url:'/pages/ai/ai'})}function goSchedule(){uni.navigateTo({url:'/pages/schedule/schedule'})}function goGroup(){uni.navigateTo({url:'/pages/group/group'})}function goNotifications(){uni.navigateTo({url:'/pages/notifications/notifications'})}function goRecovery(){uni.navigateTo({url:'/pages/recovery/recovery'})}
onShow(()=>{pageVisible=true;load()})
onHide(stopAIPolling)
onUnload(stopAIPolling)
</script>

<style lang="scss">
.page{min-height:100vh;box-sizing:border-box;padding:28rpx 28rpx 64rpx;background:linear-gradient(180deg,#fff0f7,#fffaf0 42%,#f7fbff);color:#4b2b3f}.summary{display:flex;justify-content:space-between;align-items:center;padding:30rpx 32rpx;border-radius:30rpx;background:#fff;border:1rpx solid #ffe0ea}.eyebrow{color:#ff6f91;font-size:22rpx;font-weight:900}.summary-title{margin-top:8rpx;font-size:36rpx;font-weight:900}.summary-count{color:#ff8fab;font-size:56rpx;font-weight:900}.ai-hero{display:flex;align-items:center;gap:22rpx;margin-top:20rpx;padding:32rpx;border-radius:32rpx;background:linear-gradient(135deg,#ff769f,#ffb35c);color:#fff}.ai-badge{padding:24rpx;border-radius:24rpx;background:#ffffff35;font-weight:900}.ai-copy{flex:1}.ai-title{font-size:35rpx;font-weight:900}.ai-desc{font-size:23rpx}.arrow{font-size:52rpx}.manual{margin-top:14rpx;border-radius:999rpx;background:#fff;color:#ff6f91}.tools{display:flex;gap:12rpx;margin-top:20rpx}.tool{flex:1;padding:20rpx 4rpx;border-radius:20rpx;background:#fff;text-align:center;font-size:22rpx}.recovery{background:#fff4dc}.section-head{margin:32rpx 4rpx 16rpx;font-size:32rpx;font-weight:900}.cards{display:flex;flex-direction:column;gap:18rpx}.card{padding:28rpx;border-radius:28rpx;background:#fff;border:1rpx solid #ffe0ea}.card.paused{opacity:.68}.card-head,.progress-copy{display:flex;justify-content:space-between;gap:16rpx}.plan-title{font-size:31rpx;font-weight:900}.pill{padding:8rpx 16rpx;border-radius:99rpx;background:#fff0f6;color:#ff6f91;font-size:21rpx}.plan-desc,.schedule{margin-top:12rpx;color:#606a80;font-size:24rpx}.progress{margin-top:22rpx}.track{height:14rpx;margin-top:12rpx;border-radius:99rpx;background:#edf1f6;overflow:hidden}.fill{height:100%;background:linear-gradient(90deg,#ff8fab,#ffc36a)}.taskless{margin-top:20rpx;color:#8a92a6}.invite{margin:22rpx 0 0;border-radius:99rpx;background:#fff2f7;color:#d85e82;font-size:23rpx}.empty{text-align:center;margin-top:30rpx}.empty{padding:48rpx;background:#fff;border-radius:28rpx}.empty-title{font-size:31rpx;font-weight:900}.empty-desc{margin-top:10rpx;color:#7b8498}.sheet{position:fixed;inset:0;z-index:99;display:flex;align-items:flex-end;background:#30222b75}.sheet-body{width:100%;max-height:90vh;box-sizing:border-box;padding:34rpx 30rpx 44rpx;border-radius:30rpx 30rpx 0 0;background:#fff;overflow-y:auto}.sheet-title{margin-bottom:24rpx;font-size:34rpx;font-weight:900}.field,.draft{margin-bottom:20rpx}.field>text{display:block;margin-bottom:9rpx;color:#606a80;font-size:23rpx}input,textarea,.picker{box-sizing:border-box;width:100%;padding:0 20rpx;border:1rpx solid #dfe4ed;border-radius:14rpx;background:#f9fbff;font-size:25rpx}input,.picker{height:76rpx;line-height:76rpx}textarea{height:116rpx;padding-top:16rpx}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14rpx}.weekdays{display:grid;grid-template-columns:repeat(7,1fr);gap:8rpx}.weekday{height:58rpx;line-height:58rpx;border-radius:50%;background:#f1f4f8;text-align:center}.weekday.selected{background:#ff7aa2;color:#fff}.bulk,.draft{padding:22rpx;border-radius:20rpx;background:#fff8ed}.bulk-title,.draft-date{margin-bottom:14rpx;font-weight:900}.bulk input,.bulk textarea,.draft input,.draft textarea{margin-bottom:12rpx;background:#fff}.bulk button{margin-top:12rpx;background:#ffecf2;color:#d85e82}.draft{background:#f8faff}.form-error{padding:16rpx;background:#fff1f3;color:#c44b61;white-space:pre-line}.confirm{display:flex;margin:18rpx 0;color:#606a80}.sheet-actions{display:grid;grid-template-columns:1fr 1fr;gap:14rpx}.primary{background:linear-gradient(135deg,#ff7aa2,#ffb45c);color:#fff}.secondary{background:#f3f6fb;color:#606a80}
.tools{flex-wrap:wrap}.tool{min-width:120rpx}.ai-status{display:flex;align-items:center;justify-content:space-between;gap:16rpx;margin-top:10rpx;padding:16rpx 22rpx;border-radius:18rpx;background:#fff;color:#606a80;font-size:22rpx}.ai-state{display:flex;align-items:center;gap:12rpx;min-width:0}.ai-state-dot{width:14rpx;height:14rpx;flex:0 0 auto;border-radius:50%;background:#94a3b8}.ai-state-dot.pending{background:#e0a12b}.ai-state-dot.running{background:#3978d5}.ai-state-dot.succeeded{background:#2d9b67}.ai-state-dot.failed{background:#c84d64}.ai-result{flex:0 0 auto;color:#d85e82;font-weight:900}
</style>
